  let cut;   // migration-cutover-site-r1
  try { cut = ST.validateCutover(FUNDING_MIGRATION_CUTOVER, { owner, chainId: CHAIN, oldSid: np.oldSid }); }
  catch (err) { box.innerHTML = `<h3>Funding migration</h3><p>No migration is offered to this wallet (${errText(err)}).</p>`; return; }
